         if let Some(v) = f32p(property_id::ALIGNMENT) {
             css.push_str(&format!(
                 "align-items:{};",
                 match v as u8 {
                     0 => "flex-start",
                     1 => "center",
                     2 => "flex-end",
                     _ => "flex-start",
