         // 0 = unlimited: no clamp style (the unset case above is unchanged).
         let mut no_limit = Vec::new();
         no_limit.push(Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, component_type::TEXT as u32, 0));
