#[test]
fn grid_rows_and_lazy_hgrid_tracks() {
    use pathland_core::value_type;
    use pathland_core::size;

    let build = |component: u16, width: f32, height: f32| {
        let mut opcodes = Vec::new();
        opcodes.push(Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, component as u32, 0));
        if width.is_finite() && width > 0.0 {
            opcodes.push(Opcode::new(category::STYLE, style::SET_PROPERTY, 0, 1,
                ((value_type::F32 as u32) << 16) | property_id::WIDTH as u32, width.to_bits()));
        }
        if height.is_finite() && height > 0.0 {
            opcodes.push(Opcode::new(category::STYLE, style::SET_PROPERTY, 0, 1,
                ((value_type::F32 as u32) << 16) | property_id::HEIGHT as u32, height.to_bits()));
        }
        let renderer = HtmlRenderer::new();
        renderer.render_document(&opcodes, &[], 1)
    };

    // GRID with both counts: columns from WIDTH, rows from HEIGHT.
    let g = build(component_type::GRID, 2.0, 3.0);
    assert!(g.contains("grid-template-columns:repeat(2,1fr)"), "grid columns: {g}");
    assert!(g.contains("grid-template-rows:repeat(3,1fr)"), "grid rows: {g}");
    assert!(!g.contains("width:2px") && !g.contains("height:3px"), "counts not pixels: {g}");

    // LAZY_HGRID: the fixed track is HEIGHT (rows); columns auto-flow; WIDTH is ignored.
    let h = build(component_type::LAZY_HGRID, 2.0, 3.0);
    assert!(h.contains("grid-template-rows:repeat(3,1fr)"), "hgrid rows: {h}");
    assert!(h.contains("grid-auto-flow:column;grid-auto-columns:1fr"), "hgrid auto columns: {h}");
    assert!(!h.contains("grid-template-columns:repeat(2,1fr)"), "hgrid ignores WIDTH as columns: {h}");

    // GRID with FILL WIDTH → auto-fit columns, width expands (100%).
    let f = build(component_type::GRID, size::FILL, size::HUG_CONTENT);
    assert!(f.contains("width:100%"), "FILL grid expands: {f}");
}

