    case PROP_WIDTH: {
      // A grid's WIDTH is its column count (the fixed track of vertical grids):
      // a positive Fixed count mirrors into `grid-template-columns` and NEVER
      // into a pixel width (spec §grid model); FILL → auto-fit + expand (`100%`).
      const comp = componentByNode.get(el);
      if (isGridComponent(comp)) {
        const n = f32FromBits(bits);
