     pub fn apply_adaptive_theme(
         &mut self,
         adaptive: &crate::AdaptiveTheme,
         guest: &mut Guest<'_>,
     ) -> Result<(), pathland_core::RingError> {
         self.apply_theme(&adaptive.light, guest)?;
         for (path, value) in adaptive.dark.iter() {
             let dark_path = if path.starts_with("dark.") {
                 path.to_string()
