         guest: &mut Guest<'_>,
     ) -> Result<(), pathland_core::RingError> {
         use pathland_core::tokens::TokenValue;
         match value {
             TokenValue::Str(s) => {
                 let ref_ = guest
                     .alloc_str(s)
                     .map_err(|_| pathland_core::RingError::Full)?;
