     fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
         f.debug_struct("Node")
             .field("id", &self.id)
             .field("component", &self.component)
             .field("children", &self.children)
             .field("properties", &self.properties)
             .field("token_properties", &self.token_properties)
