         self.tree(tree::CREATE_NODE, id, component as u32, 0);
     }

     fn insert(&mut self, parent: u32, child: u32) {
         self.tree(tree::INSERT_CHILD, parent, child, pathland_core::APPEND);
     }

     fn set_text(&mut self, id: u32, text: &str) {
