   if (el.parentNode) {
     el.parentNode.replaceChild(wrapper, el);
   }
   const id = Number(wrapper.getAttribute("data-pathland-id") ?? 0);
   if (id) {
     r.byId.set(id, wrapper);
   }
   const c = componentByNode.get(el);
   if (c !== undefined) {
     componentByNode.set(wrapper, c);
   }
   return wrapper;
 }
